#include <string>
#include <cstdint>

void PutVarint32(std::string* dst, uint32_t v) {
    uint8_t buf[5];
    uint8_t* ptr = buf;

    if (v < (1 << 7)) {
        *ptr++ = v;
    } else if (v < (1 << 14)) {
        *ptr++ = (v & 0x7f) | 0x80;
        *ptr++ = v >> 7;
    } else if (v < (1 << 21)) {
        *ptr++ = (v & 0x7f) | 0x80;
        *ptr++ = ((v >> 7) & 0x7f) | 0x80;
        *ptr++ = v >> 14;
    } else if (v < (1 << 28)) {
        *ptr++ = (v & 0x7f) | 0x80;
        *ptr++ = ((v >> 7) & 0x7f) | 0x80;
        *ptr++ = ((v >> 14) & 0x7f) | 0x80;
        *ptr++ = v >> 21;
    } else {
        *ptr++ = (v & 0x7f) | 0x80;
        *ptr++ = ((v >> 7) & 0x7f) | 0x80;
        *ptr++ = ((v >> 14) & 0x7f) | 0x80;
        *ptr++ = ((v >> 21) & 0x7f) | 0x80;
        *ptr++ = v >> 28;
    }

    dst->append(reinterpret_cast<const char*>(buf), ptr - buf);
}

